begin;
select no_plan();
insert into auth.users(id,email) values
 ('11111111-1111-4111-8111-111111111111','chat@example.test'),
 ('22222222-2222-4222-8222-222222222222','other-chat@example.test');
select public.get_or_create_account_profile('11111111-1111-4111-8111-111111111111','chat@example.test',false);
select public.get_or_create_account_profile('22222222-2222-4222-8222-222222222222','other-chat@example.test',true);
select public.submit_fetch_items('11111111-1111-4111-8111-111111111111',array['https://chat.test/one','https://chat.test/two']);
select public.submit_fetch_items('22222222-2222-4222-8222-222222222222',array['https://chat.test/foreign']);
update public.items set status='completed' where original_url in ('https://chat.test/one','https://chat.test/two','https://chat.test/foreign');
insert into public.source_contents(item_id,user_id,acquisition_method,content,content_hash)
 select id,user_id,'fetch',repeat('Source evidence. ',30),'hash' from public.items;
insert into public.assessments(item_id,user_id,note,criteria,score,verdict,threshold_snapshot)
 select id,user_id,'Saved analysis','[]',75,'valuable',60 from public.items;
create temporary table chat_item as select id from public.items where original_url='https://chat.test/one';
select is((select count(*)::int from public.begin_chat_turn('22222222-2222-4222-8222-222222222222',(select id from chat_item),'aaaaaaaa-1111-4111-8111-111111111111','Foreign?')),0,'admin cannot start another owner chat');
create temporary table claimed as select * from public.begin_chat_turn('11111111-1111-4111-8111-111111111111',(select id from chat_item),'aaaaaaaa-1111-4111-8111-111111111111','Explain the analysis');
select ok((select claimed from claimed),'first request claims execution');
select is((select claimed from public.begin_chat_turn('11111111-1111-4111-8111-111111111111',(select id from chat_item),'aaaaaaaa-1111-4111-8111-111111111111','Explain the analysis')),false,'duplicate request never claims execution');
select is((select count(*)::int from public.begin_chat_turn('11111111-1111-4111-8111-111111111111',(select id from chat_item),'aaaaaaaa-2222-4222-8222-222222222222','Another?')),0,'second pending question is blocked');
select is((select count(*)::int from public.list_chat_turns('22222222-2222-4222-8222-222222222222',(select id from chat_item))),0,'foreign history stays private');
select is((select count(*)::int from public.reserve_chat_call('22222222-2222-4222-8222-222222222222','aaaaaaaa-1111-4111-8111-111111111111','decision',0.15)),0,'foreign turn cannot reserve cost');
select is((select count(*)::int from public.reserve_chat_call('11111111-1111-4111-8111-111111111111','aaaaaaaa-1111-4111-8111-111111111111','decision',0.15)),0,'answer model requires classification reservation');
select is((select count(*)::int from public.reserve_chat_call('22222222-2222-4222-8222-222222222222','aaaaaaaa-1111-4111-8111-111111111111','classification',0.002688)),0,'foreign classifier cost cannot be reserved');
create temporary table classifier_cost as select * from public.reserve_chat_call('11111111-1111-4111-8111-111111111111','aaaaaaaa-1111-4111-8111-111111111111','classification',0.002688);
select is((select count(*)::int from classifier_cost),1,'classification reserves shared budget');
select is((select count(*)::int from public.reserve_chat_call('11111111-1111-4111-8111-111111111111','aaaaaaaa-1111-4111-8111-111111111111','classification',0.002688)),0,'classification cannot be replayed');
select public.record_chat_generation('11111111-1111-4111-8111-111111111111',(select id from classifier_cost),'gen-classifier-one');
select is((select generation_id from public.usage_reservations where id=(select id from classifier_cost)),'gen-classifier-one','classifier generation saved for reconciliation');
select public.settle_analysis('11111111-1111-4111-8111-111111111111',(select id from classifier_cost),0.00002);
select is((select count(*)::int from public.reserve_chat_call('11111111-1111-4111-8111-111111111111','aaaaaaaa-1111-4111-8111-111111111111','classification',0.002688)),0,'settled classification cannot repeat');
create temporary table decision_cost as select * from public.reserve_chat_call('11111111-1111-4111-8111-111111111111','aaaaaaaa-1111-4111-8111-111111111111','decision',0.15);
select is((select count(*)::int from decision_cost),1,'decision reserves shared budget');
select is((select count(*)::int from public.reserve_chat_call('11111111-1111-4111-8111-111111111111','aaaaaaaa-1111-4111-8111-111111111111','decision',0.15)),0,'decision reservation cannot be replayed');
select public.record_chat_generation('11111111-1111-4111-8111-111111111111',(select id from decision_cost),'gen-chat-one');
select public.settle_analysis('11111111-1111-4111-8111-111111111111',(select id from decision_cost),0.01);
select is((select count(*)::int from public.reserve_chat_call('11111111-1111-4111-8111-111111111111','aaaaaaaa-1111-4111-8111-111111111111','decision',0.15)),0,'settled call cannot be repeated');
create temporary table search_cost as select * from public.reserve_chat_call('11111111-1111-4111-8111-111111111111','aaaaaaaa-1111-4111-8111-111111111111','search',0.005);
select is((select count(*)::int from search_cost),1,'one search admitted');
select public.settle_analysis('11111111-1111-4111-8111-111111111111',(select id from search_cost),0.005);
select is((select count(*)::int from public.reserve_chat_call('11111111-1111-4111-8111-111111111111','aaaaaaaa-1111-4111-8111-111111111111','search',0.005)),0,'a second search is impossible even after settlement');
select is((select count(*)::int from public.reserve_chat_call('11111111-1111-4111-8111-111111111111','aaaaaaaa-1111-4111-8111-111111111111','answer',0.15)),1,'one final generation admitted');
select public.set_user_budget('11111111-1111-4111-8111-111111111111',0);
select is((select reserved_usd from public.get_usage_summary('11111111-1111-4111-8111-111111111111')),0.15::numeric,'unknown final cost remains reserved');
select is((select spent_usd from public.get_usage_summary('11111111-1111-4111-8111-111111111111')),0.01502::numeric,'actual model and search costs share ledger');
select throws_ok($$insert into public.chat_turns(id,item_id,user_id,question,status) values(gen_random_uuid(),(select id from chat_item),'22222222-2222-4222-8222-222222222222','Forged','failed')$$,'23503',null,'composite ownership forbids foreign turn');
select throws_ok($$insert into public.usage_reservations(user_id,month,amount_usd,chat_turn_id) values('22222222-2222-4222-8222-222222222222',date_trunc('month',now())::date,0.15,'aaaaaaaa-1111-4111-8111-111111111111')$$,'23503',null,'composite ownership forbids foreign billing attachment');
set local role authenticated;
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is((select count(*)::int from public.chat_turns),0,'RLS hides another users chat');
select throws_ok($$select public.begin_chat_turn('11111111-1111-4111-8111-111111111111',(select id from public.items limit 1),gen_random_uuid(),'Browser write')$$,'42501',null,'browser cannot invoke chat mutation');
reset role;
update public.chat_turns set deadline=now()-interval '1 second' where id='aaaaaaaa-1111-4111-8111-111111111111';
select is((select status from public.list_chat_turns('11111111-1111-4111-8111-111111111111',(select id from chat_item))),'failed','expired execution becomes explicit failure');
select is((select count(*)::int from public.finish_chat_turn('11111111-1111-4111-8111-111111111111','aaaaaaaa-1111-4111-8111-111111111111','{"status":"completed","answer":[],"sources":[]}')),0,'late completion fenced after interruption');
select is((select claimed from public.begin_chat_turn('11111111-1111-4111-8111-111111111111',(select id from chat_item),'aaaaaaaa-1111-4111-8111-111111111111','Explain the analysis')),false,'expired request UUID never re-executes');
select is((select claimed from public.begin_chat_turn('11111111-1111-4111-8111-111111111111',(select id from chat_item),'aaaaaaaa-2222-4222-8222-222222222222','New explicit question')),true,'new explicit question can proceed');
select is((select count(*)::int from public.reserve_chat_call('11111111-1111-4111-8111-111111111111','aaaaaaaa-2222-4222-8222-222222222222','classification',0.002688)),0,'zero budget blocks classification');
select public.delete_items('11111111-1111-4111-8111-111111111111',array(select id from chat_item),true);
select is((select count(*)::int from public.chat_turns),0,'deletion cascades all conversation content');
select is((select count(*)::int from public.usage_reservations where chat_slot is not null and chat_turn_id is null),4,'chat charge records survive content deletion');
select public.record_chat_generation('11111111-1111-4111-8111-111111111111',(select id from public.usage_reservations where chat_slot='answer'),'late-chat-generation');
select is((select generation_id from public.usage_reservations where chat_slot='answer'),'late-chat-generation','late cost metadata can still reconcile');
select is((select count(*)::int from public.finish_chat_turn('11111111-1111-4111-8111-111111111111','aaaaaaaa-1111-4111-8111-111111111111','{"status":"completed","answer":[],"sources":[]}')),0,'late answer cannot recreate deleted content');
select public.set_user_budget('11111111-1111-4111-8111-111111111111',10);
select public.begin_chat_turn('11111111-1111-4111-8111-111111111111',(select id from public.items where original_url='https://chat.test/two'),'bbbbbbbb-1111-4111-8111-111111111111','Saved follow-up');
select public.reserve_chat_call('11111111-1111-4111-8111-111111111111','bbbbbbbb-1111-4111-8111-111111111111','classification',0.002688);
select public.reserve_chat_call('11111111-1111-4111-8111-111111111111','bbbbbbbb-1111-4111-8111-111111111111','decision',0.15);
select is((select status from public.finish_chat_turn('11111111-1111-4111-8111-111111111111','bbbbbbbb-1111-4111-8111-111111111111','{"status":"completed","answer":[{"text":"Supported answer","citations":[]}],"sources":[{"id":"chat","url":"https://source.test","text":"Saved fetched evidence"}]}')),'completed','verified application result persists');
select is((select question from public.list_chat_turns('11111111-1111-4111-8111-111111111111',(select id from public.items where original_url='https://chat.test/two'))),'Saved follow-up','history restores the question');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is((select count(*)::int from public.chat_turns),1,'owner can read own chat via RLS');
select throws_ok($$insert into public.chat_turns(id,item_id,user_id,question) values(gen_random_uuid(),gen_random_uuid(),'11111111-1111-4111-8111-111111111111','Browser mutation')$$,'42501',null,'browser direct mutations forbidden');
reset role;
update public.items set expires_at=now()-interval '1 second' where original_url='https://chat.test/two';
select is((select count(*)::int from public.list_chat_turns('11111111-1111-4111-8111-111111111111',(select id from public.items where original_url='https://chat.test/two'))),0,'expired content is unavailable to chat');
update public.items set status='queued' where original_url='https://chat.test/two';
select is((select count(*)::int from public.begin_chat_turn('11111111-1111-4111-8111-111111111111',(select id from public.items where original_url='https://chat.test/two'),gen_random_uuid(),'Incomplete?')),0,'incomplete analysis cannot start chat');
select * from finish();
rollback;
